// Independent auditor D13 public-contract probe (no database): viewer2/clock2/live4 invariants and
// separation from the retained viewer1/clock1/live2/live3 codecs; client helpers; player move list.
import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import * as C from './packages/contracts/dist/index.js';
import { isPlayerMove } from './packages/contracts/dist/player-moves.js';
import { createRecordedCore } from './packages/engine-adapter/dist/replay.js';
import { timeoutWarning, matchResult } from './packages/match-client/dist/index.js';

const out = {}, clone = v => JSON.parse(JSON.stringify(v));
const refuses = (fn, label) => { assert.throws(fn, label); return true; };
const policy = { schemaVersion: 2, id: 'audit-d13', profile: 'qualification', mode: 'dynamic', initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0, timeoutLimit: 3 };
const core = createRecordedCore({ players: ['p1', 'p2'], startTimestamp: 1000, clock: policy }, randomBytes(32));
const live = core.project({ kind: 'participant', playerId: 'p1' }, 'audit-match');
assert.equal(live.schemaVersion, 2); assert.equal(live.endReason, null);
const chooser = core.facade.status().choosingFirstPlayer;
assert.equal(core.facade.submit({ actor: 'p2', expectedRevision: 0, timestamp: 1000, commandId: 'c', move: 'concede', input: {} }).accepted, true);
const ended = core.project({ kind: 'participant', playerId: 'p1' }, 'audit-match');
assert.equal(ended.endReason, 'concession'); assert.equal(ended.winner, 'p1');

// viewer2 invariants
const v = {};
v.endedWithoutReason = refuses(() => C.parseViewerProjection({ ...ended, endReason: null }));
v.reasonWhileLive = refuses(() => C.parseViewerProjection({ ...live, endReason: 'timeout' }));
v.endedWithoutWinner = refuses(() => C.parseViewerProjection({ ...ended, winner: null }));
v.outsiderWinner = refuses(() => C.parseViewerProjection({ ...ended, winner: 'p3' }));
v.unknownReason = refuses(() => C.parseViewerProjection({ ...ended, endReason: 'forfeit' }));
v.missingReason = refuses(() => { const x = clone(ended); delete x.endReason; C.parseViewerProjection(x); });
// legacy viewer1 kept exact and separate
const legacy = clone(live); delete legacy.endReason; legacy.schemaVersion = 1;
assert.equal(typeof C.encodeLegacyViewerProjection(legacy), 'string');
v.legacyRejectsReason = refuses(() => C.encodeLegacyViewerProjection({ ...legacy, endReason: null }));
v.currentRejectsLegacy = refuses(() => C.decodeViewerProjection(JSON.stringify(legacy)));
v.legacyRejectsCurrent = refuses(() => C.decodeLegacyViewerProjection(JSON.stringify(live)));
out.viewer = v;

// clock2 invariants
const clock = { schemaVersion: 2, policyId: 'audit-d13', timeoutLimit: 3, stateVersion: 0, clockRevision: 0, status: 'running', serverNowMs: 5000, deadlineMs: 9000, activePlayerId: 'p1', players: [{ playerId: 'p1', remainingMs: 4000, timeoutCount: 2 }, { playerId: 'p2', remainingMs: 4000, timeoutCount: 0 }], pauseReason: null };
assert.equal(C.parseClockProjection(clock).players[0].timeoutCount, 2);
const k = {};
const withCount = (n, status = 'running') => { const x = clone(clock); x.players[0].timeoutCount = n; if (status === 'ended') { x.status = 'ended'; x.deadlineMs = null; } return x; };
k.atLimitWhileRunning = refuses(() => C.parseClockProjection(withCount(3)));
assert.equal(C.parseClockProjection(withCount(3, 'ended')).status, 'ended'); k.atLimitWhenEnded = 'accepted';
k.overLimitEnded = refuses(() => C.parseClockProjection(withCount(4, 'ended')));
k.limitZero = refuses(() => C.parseClockProjection({ ...clock, timeoutLimit: 0 }));
k.limitEleven = refuses(() => C.parseClockProjection({ ...clock, timeoutLimit: 11 }));
k.extraField = refuses(() => C.parseClockProjection({ ...clock, winner: 'p2' }));
const legacyClock = clone(clock); legacyClock.schemaVersion = 1; delete legacyClock.timeoutLimit; for (const p of legacyClock.players) delete p.timeoutCount;
assert.equal(C.parseLegacyClockProjection(legacyClock).schemaVersion, 1);
k.currentRejectsLegacy = refuses(() => C.parseClockProjection(legacyClock));
k.legacyRejectsCurrent = refuses(() => C.parseLegacyClockProjection(clock));
k.policyLimitBounds = [0, 1, 10, 11, 2.5].map(n => { try { C.parseClockPolicy({ ...policy, timeoutLimit: n }); return n + ':ok'; } catch { return n + ':refused'; } });
k.policyV1Refused = refuses(() => { const p = clone(policy); p.schemaVersion = 1; delete p.timeoutLimit; C.parseClockPolicy(p); });
out.clock = k;

// live4 snapshot frames
const frame = (payload, clk, version = 4) => ({ type: 'snapshot', protocolVersion: version, matchId: 'audit-match', sequence: 1, stateVersion: payload.stateVersion, correlationId: 'c1', releaseId: 'r1', projectionType: 'viewer', payload, ...(clk === undefined ? {} : { clock: clk }) });
const l = {};
const liveClock = { ...clone(clock), stateVersion: live.stateVersion, players: [{ playerId: 'p1', remainingMs: 4000, timeoutCount: 0 }, { playerId: 'p2', remainingMs: 4000, timeoutCount: 0 }] };
assert.equal(typeof C.encodeLive4ServerFrame(frame(live, liveClock)), 'string');
assert.equal(typeof C.encodeLive4ServerFrame(frame(live, null)), 'string'); l.untimedNullClock = 'accepted';
l.clockRequired = refuses(() => C.encodeLive4ServerFrame(frame(live, undefined)));
l.timeoutWithoutClock = refuses(() => C.encodeLive4ServerFrame(frame({ ...ended, endReason: 'timeout' }, null)));
l.endedMismatch = refuses(() => C.encodeLive4ServerFrame(frame(ended, { ...liveClock, stateVersion: ended.stateVersion })));
l.legacyPayloadInLive4 = refuses(() => C.encodeLive4ServerFrame(frame(legacy, liveClock)));
l.viewer2InLive3 = refuses(() => C.encodeLive3ServerFrame(frame(live, legacyClock, 3)));
l.clock2InLive3 = refuses(() => C.encodeLive3ServerFrame(frame(legacy, liveClock, 3)));
l.viewer2InLive2 = refuses(() => C.encodeLiveServerFrame(frame(live, undefined, 2)));
const legacyLive3 = { ...clone(legacyClock), stateVersion: legacy.stateVersion };
assert.equal(typeof C.encodeLive3ServerFrame(frame(legacy, legacyLive3, 3)), 'string'); l.live3StillEncodes = true;
assert.equal(typeof C.encodeLiveServerFrame(frame(legacy, undefined, 2)), 'string'); l.live2StillEncodes = true;
const cmd = { type: 'command', protocolVersion: 4, matchId: 'audit-match', commandId: 'x1', correlationId: 'c1', expectedStateVersion: 0, intent: { kind: 'concede', input: {} } };
assert.equal(C.parseLive4Command(cmd).protocolVersion, 4); l.forfeitIntentRefused = refuses(() => C.parseLive4Command({ ...cmd, intent: { kind: 'forfeitGame', input: { winnerId: 'p1', reason: 'timeout' } } }));
l.pending3BindsCommand4 = (() => { try { return C.parseTransportPending({ schemaVersion: 3, actorId: 'p1', command: cmd }) ? 'accepted' : 'refused'; } catch (e) { return 'refused:' + e.message; } })();
l.pending2RejectsCommand4 = refuses(() => C.parseTransportPending({ schemaVersion: 2, actorId: 'p1', command: cmd }));
out.live = l;

// client helpers and the player move list
out.client = {
  warningNone: timeoutWarning({ ...liveClock, players: [{ playerId: 'p1', remainingMs: 1, timeoutCount: 0 }, { playerId: 'p2', remainingMs: 1, timeoutCount: 0 }] }, 'p1'),
  warningOne: timeoutWarning({ ...liveClock, players: [{ playerId: 'p1', remainingMs: 1, timeoutCount: 1 }, { playerId: 'p2', remainingMs: 1, timeoutCount: 0 }] }, 'p1'),
  warningLast: timeoutWarning({ ...liveClock, players: [{ playerId: 'p1', remainingMs: 1, timeoutCount: 2 }, { playerId: 'p2', remainingMs: 1, timeoutCount: 0 }] }, 'p1'),
  warningOpening: timeoutWarning(liveClock, 'p1', true),
  warningLimit1: timeoutWarning({ ...liveClock, timeoutLimit: 1 }, 'p1'),
  resultLive: matchResult(live), resultEnded: matchResult(ended),
  playerMoves: { concede: isPlayerMove('concede'), forfeitGame: isPlayerMove('forfeitGame') },
};
assert.equal(out.client.playerMoves.forfeitGame, false); assert.equal(out.client.warningLast, 'Next timeout loses the game');
assert.equal(out.client.warningLimit1, 'Next timeout loses the game'); assert.equal(l.pending3BindsCommand4, 'accepted');
console.log(JSON.stringify(out));
